import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { throwError } from 'rxjs';
import { user } from 'src/app/models/user';
import { AuthService } from 'src/app/service/auth.service';

@Component({
  selector: 'app-register-page',
  templateUrl: './register-page.component.html',
  styleUrls: ['./register-page.component.css']
})
export class RegisterPageComponent {
  newUser : user = {
    id: '',
    name: '',
    surname: '',
    role: 'coordinator',
    email: '',
    password: ''
  }
  loading =false;
  success = false;
  error = '';

  constructor(
    private auth: AuthService,
    private readonly router: Router
  ){}

  register() {
    console.log(this.newUser)
    if(!this.newUser.name || !this.newUser.surname || !this.newUser.email || !this.newUser.password)
      throwError(() => new Error("Fields are invalid"));

    this.auth.register(this.newUser).subscribe({
      next: (user) => {
        this.loading = false;
        this.success = true;
        console.log('Registration for user: ', this.newUser);
      },
      error: (err) => {
        this.loading = false;
        this.error = err.message || 'Registration failed'
        console.log('Registration failed');
      }
    });
  }
}
<div class="register-form-div">
  <form class="register-form">

    <h2>REGISTER</h2>

    <div class="reg-form">

      <div class="input">
        <label>First Name</label>
        <input [(ngModel)]="newUser.name" type="text" id="name" name="name" placeholder="First Name" class="inputVal">
      </div>

      <div class="input">
        <label>Surname</label>
        <input [(ngModel)]="newUser.surname" type="text" id="surname" name="surname" placeholder="Last Name" class="inputVal">
      </div>


      <div class="input"><label>Role</label>
        <select [(ngModel)]="newUser.role" id="role" name="role" class="inputVal">
          <option value="coordinator">Coordinator</option>
          <option value="respondent">Respondent</option>
        </select>
      </div>


      <div class="input"> <label>Email</label>
        <input [(ngModel)]="newUser.email" type="email" id="email" name="email" placeholder="email" class="inputVal">
      </div>


      <div class="input"><label>Password</label>
        <input [(ngModel)]="newUser.password" type="password" id="password" name="password" placeholder="password" class="inputVal">
      </div>


    </div>
    <div class="register-btn">
    <button (click)="register()" type="button" class="register">Register</button>

    <div *ngIf="success" class="success">
      Account Created! You can now <a routerLink="/login">Log In</a>
    </div>
 </div>
  </form>
</div>
